import{_ as l,C as o,o as t,c as p,j as s,a as e,E as c,w as r,a2 as i}from"./chunks/framework.C2TvIV46.js";const v=JSON.parse('{"title":"begin","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/elements/begin.md","filePath":"ja/language/elements/begin.md"}'),g={name:"ja/language/elements/begin.md"};function d(m,a,b,u,x,_){const n=o("AvailabilityCard");return t(),p("div",null,[a[1]||(a[1]=s("h1",{id:"begin",tabindex:"-1"},[e("begin "),s("a",{class:"header-anchor",href:"#begin","aria-label":'Permalink to "begin"'},"​")],-1)),c(n,{reach:"partial",halo4:"yes",h2a:"yes"},{default:r(()=>[...a[0]||(a[0]=[s("p",null,[s("code",null,"begin"),e(" アクションは Halo: Reach の Master Chief Collection 版で追加され、Xbox 360 版の Halo: Reach では利用できません。")],-1)])]),_:1}),a[2]||(a[2]=i(`<p><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger#action-scope">アクションスコープ</a> 内に明示的な <strong>サブブロック</strong> を開きます。コンパイラは <code>begin</code> をアクションオペコードへ下げますが、ソース上では <code>condition</code>、<code>action</code>、<code>temporary</code>、<code>or</code> と並ぶスコープ要素のように振る舞います。</p><p>出荷での主な用途は <strong>if/elseif 風の分岐</strong> です。連続する複数の <code>begin</code>/<code>end</code> ペアがあり、各ブロックが独自の条件を持ちます。あるブロック内の条件が失敗しても、そのブロックだけが停止し — 次の <code>begin</code> ブロックは依然として実行されます。</p><h2 id="winter-contingency-からの例" tabindex="-1">Winter Contingency からの例 <a class="header-anchor" href="#winter-contingency-からの例" aria-label="Permalink to &quot;Winter Contingency からの例&quot;">​</a></h2><p>Reach MCC の <code>tu1_winter_contingency.txt</code> は、<code>action for_each team</code> 内の <code>begin</code> ブロックでラウンドタイムアウト時の勝者判定を書き換えました。各ブロックが異なる凍結プレイヤー数を検査し、引き分け追跡状態を更新します。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">general</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">round_time_limit</span><span class="megalo-text"> </span><span class="megalo-operator">&gt;</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">timer_expired</span><span class="megalo-text"> </span><span class="megalo-variable">round_timer</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players</span><span class="megalo-text"> k_maximum_team_size</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary </span><span class="megalo-type">team</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players_team</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action for_each </span><span class="megalo-type">team</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> active_teams_count </span><span class="megalo-operator">+=</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">condition </span><span class="megalo-function">team_is_active</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">begin</span></span>
<span class="line"><span class="megalo-text">			</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">players_frozen </span><span class="megalo-operator">==</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players</span></span>
<span class="line"><span class="megalo-text">			</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> teams_tied </span><span class="megalo-operator">=</span><span class="megalo-text"> </span><span class="megalo-variable">true</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">begin</span></span>
<span class="line"><span class="megalo-text">			</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">players_frozen </span><span class="megalo-operator">&lt;</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players</span></span>
<span class="line"><span class="megalo-text">			</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players</span><span class="megalo-text"> </span><span class="megalo-operator">=</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">players_frozen</span></span>
<span class="line"><span class="megalo-text">			</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players_team</span><span class="megalo-text"> </span><span class="megalo-operator">=</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p><code>begin</code> がなければ、フラットな条件は <strong>AND</strong> でつながるため — 最初の失敗した比較が残りの反復を止めてしまいます。別ブロックにすると、各分岐が独立に走り、<code>if</code> / <code>else if</code> のようになります。</p><p>HREK の同じトリガーには、コメントとして古い Reach パターンが残っています。単一の <code>for_each</code> 本体で、<code>or</code> チェーン条件が elseif 分岐として働く形です。MCC は（Halo 4 から移植した）<code>begin</code> オペコードを追加し、そのロジックを明示的なサブブロックとして書けるようにしました。</p><h2 id="構文" tabindex="-1">構文 <a class="header-anchor" href="#構文" aria-label="Permalink to &quot;構文&quot;">​</a></h2><p><code>begin</code> は <code>action begin</code> ではなく、単独行で書きます。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">begin</span></span>
<span class="line"><span class="megalo-text">	[&lt;conditions, actions, temporaries, nested begin/end pairs&gt;]</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>合法な内容は他のアクションスコープと同じです。<code>condition</code>、<code>or</code>、<code>action</code>、<code>temporary</code>、および入れ子の <code>begin</code>/<code>end</code> ペア。</p><h2 id="現れる場所" tabindex="-1">現れる場所 <a class="header-anchor" href="#現れる場所" aria-label="Permalink to &quot;現れる場所&quot;">​</a></h2><p><code>begin</code> ブロックはアクションスコープが有効なところならどこでも有効です。</p><ul><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger"><code>trigger</code></a> 本体内</li><li><code>action for_each</code> サブトリガー内</li><li>別の <code>begin</code> ブロック内に入れ子</li></ul><h2 id="規則" tabindex="-1">規則 <a class="header-anchor" href="#規則" aria-label="Permalink to &quot;規則&quot;">​</a></h2><p><strong>独立ブロック</strong> — 連続する <code>begin</code>/<code>end</code> ペアは順に評価されます。ブロック <em>N</em> 内の偽条件は、ブロック <em>N + 1</em> の実行を妨げません。</p><p><strong>アクション予算</strong> — 各 <code>begin</code> 行は、ブロック内のアクションに加えて、スクリプトの 1024 アクション上限に対して <strong>アクション 1 つ</strong> としてカウントされます。</p><p><strong>一時変数</strong> — <code>begin</code> ブロック内の <a href="/MegaloEvolved/beta/docs/ja/language/variable-model#temporary-variables"><code>temporary</code></a> 宣言は、そのブロック（およびその中の入れ子ブロック）にスコープされます。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger#action-scope">trigger — アクションスコープ</a> — トリガー内で有効なキーワード</li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger">trigger</a> — 実行と <code>for_each</code></li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger/condition#or">条件 — OR</a> — <code>begin</code> 以前の elseif パターン</li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger/action">action</a> — ブロック内の命令オペコード</li><li><a href="/MegaloEvolved/beta/docs/ja/language/variable-model#temporary-variables">変数モデル — 一時変数</a></li></ul>`,20))])}const y=l(g,[["render",d]]);export{v as __pageData,y as default};
